        }

        public void LoadInfo()
        {
            if (TeachingTimeResearchID != null)
            {
                objData = new SIM_TeachingTimeResearch();
                objData.TeachingTimeResearchID = TeachingTimeResearchID;
                if (objData.Get())
                {
