                    txtResearchHour.Text = FormatDecimal(objData.ResearchHour);
                    txtSavePrev.Text = FormatDecimal(objData.SavePrev);
                    txtResearchNow.Text = FormatDecimal(objData.ResearchNow);
                    txtResearchContent.Text = objData.ResearchContent;
                    txtDecisionNo.Text = objData.DecisionNo;
                    lblTitlePage.Text = "Sửa giờ NCKH giảng viên";
                    LoadTeacherName();
                    udpAll.Update();
                }
            }
        }

        public void LoadNew(object teacherID, object teacherName, object yearID, object semester)
        {
            Clear();
            if (teacherID == null || teacherID.ToString().Trim() == "")
            {
                MsgBox.ShowWarning("Bạn phải chọn giảng viên trước khi thêm mới!");
                return;
            }
            if (yearID == null || semester == null)
            {
                MsgBox.ShowWarning("Bạn phải chọn niên, kỳ!");
                return;
            }

            hidTeacherID.Value = teacherID.ToString();
            hidYearID.Value = yearID.ToString();
            hidSemester.Value = semester.ToString();
            lblTeacherName.Text = teacherName != null ? teacherName.ToString() : teacherID.ToString();
            lblYearSemester.Text = String.Format("{0} - HK {1}", yearID, semester);
            lblTitlePage.Text = "Thêm giờ NCKH giảng viên";
            udpAll.Update();
        }

        private void LoadTeacherName()
        {
            if (hidTeacherID.Value == "")
                return;

            SIM_Teacher objTeacher = new SIM_Teacher();
            objTeacher.TeacherID = hidTeacherID.Value;
            if (objTeacher.Get())
                lblTeacherName.Text = objTeacher.TeacherFirstName + " " + objTeacher.TeacherLastName;
        }

        private string FormatDecimal(object value)
        {
            if (value == null || value == DBNull.Value || value.ToString() == "")
                return "";
            return Convert.ToDecimal(value).ToString("0.##");
        }

        private decimal? ParseDecimal(string text)
        {
            if (text == null || text.Trim() == "")
                return null;
            decimal decValue = 0;
            if (decimal.TryParse(text.Trim(), out decValue))
                return decValue;
            return null;
        }

        public bool SaveData()
        {
            if (hidTeacherID.Value.Trim() == "")
            {
                MsgBox.ShowWarning("Thiếu thông tin giảng viên!");
                return false;
            }
            if (hidYearID.Value.Trim() == "" || hidSemester.Value.Trim() == "")
            {
                MsgBox.ShowWarning("Thiếu thông tin năm học, học kỳ!");
                return false;
            }

            objData.TeachingTimeResearchID = TeachingTimeResearchID;
            objData.TeacherID = hidTeacherID.Value.Trim();
            objData.YearID = Convert.ToInt32(hidYearID.Value);
            objData.Semester = Convert.ToInt32(hidSemester.Value);
            objData.TeachHour = ParseDecimal(txtTeachHour.Text);
            objData.ResearchHour = ParseDecimal(txtResearchHour.Text);
            objData.SavePrev = ParseDecimal(txtSavePrev.Text);
            objData.ResearchNow = ParseDecimal(txtResearchNow.Text);
            objData.ResearchContent = txtResearchContent.Text.Trim();
            objData.DecisionNo = txtDecisionNo.Text.Trim();

            if (TeachingTimeResearchID == null)
                objData.CreatedUser = User.UserName;
            else
                objData.UpdatedUser = User.UserName;

            if (!objData.AddOrEdit())
            {
                string strError = "Lỗi khi lưu dữ liệu!";
                if (objData.ErrorException != null)
                    strError = strError + " " + objData.ErrorException.Message;
                MsgBox.ShowError(strError);
                return false;
            }

            TeachingTimeResearchID = objData.TeachingTimeResearchID;
            return true;
        }

        public void ShowPopup()
        {
            string script = "var modalEl = document.getElementById('myModal_" + this.ClientID + "');" +
                "if(modalEl) { var bsModal = new bootstrap.Modal(modalEl); bsModal.show(); }";
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_OpenModal_" + this.ClientID, script, true);
        }

        public void ClosePopup()
        {
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_CloseModal_" + this.ClientID,
                "var m=document.getElementById('myModal_" + this.ClientID + "');if(m){var b=bootstrap.Modal.getInstance(m);if(b){b.hide();}}", true);
        }

        #endregion

        protected void Page_Load(object sender, EventArgs e)
        {
            if (User == null)
                return;
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                ClosePopup();
                if (SavedCompleted != null)
                    SavedCompleted(this, e);
            }
        }

        public event EventHandler SavedCompleted = null;
    }
}

