public bool AddOrEdit()
{
    if (!bolIsExistIData)
        objIData = DCore.Data.CreateData();
    try
    {
        objIData.CreateNewStoredProcedure("SIM_TeachingTimeResearch_AddOrEdit");
        objIData.AddParameter(P_TeachingTimeResearchID, this.lngTeachingTimeResearchID);
        objIData.AddParameter(P_TeacherID, this.strTeacherID);
        objIData.AddParameter(P_YearID, this.intYearID);
        objIData.AddParameter(P_Semester, this.intSemester);
        objIData.AddParameter(P_TeachHour, this.decTeachHour);
        objIData.AddParameter(P_ResearchHour, this.decResearchHour);
        objIData.AddParameter(P_SavePrev, this.decSavePrev);
        objIData.AddParameter(P_ResearchNow, this.decResearchNow);
        objIData.AddParameter(P_ResearchContent, this.strResearchContent);
        objIData.AddParameter(P_DecisionNo, this.strDecisionNo);
        objIData.AddParameter(P_CreatedUser, this.strCreatedUser);
        objIData.AddParameter(P_UpdatedUser, this.strUpdatedUser);
        this.lngTeachingTimeResearchID = Convert.ToInt64(objIData.ExecStoreToString());
        return true;
    }
    catch (Exception objEx)
    {
        if (bolIsExistIData)
            this.RollBackTransaction();
        new SystemError(SystemConfig.ConnectionString, "Lỗi thêm thông tin SIM_TeachingTimeResearch_AddOrEdit", objEx);
        this.objErrorException = objEx;
        return false;
    }
    finally
    {
        if (!bolIsExistIData)
            objIData.Disconnect();
    }
}

